/**
 * Devnet run of the signer jobs (apps/signer/src/jobs): one tiny refund and one creator-fee claim,
 * through the real job code, the real keystore (refund) and the real cluster. Devnet only: the RPC
 * URL must contain "devnet" (lib/env.ts), otherwise nothing runs.
 *
 *   pnpm exec tsx src/signer-claims.ts        (from scripts/devnet-tests, RPC_URL in the env)
 *
 * 1. Refund (0.001 SOL). The cashbox stand-in is a key GENERATED by the signer keystore in
 *    `.state/signer-claims/keystore` (throwaway passphrase in `.state`, devnet only); the funder
 *    gives it rent + a little SOL. The `client` wallet pays 0.001 SOL to it with the payment memo
 *    `forge:job:<jobId>`. A twice-failed build job + that payment are seeded in an in-memory store
 *    (persisted in `.state/state.json` between runs). The refunds job verifies the payment at
 *    finalized commitment and refunds it; a second run proves nothing is sent twice.
 * 2. Creator claim. The wave-1 pools whose creator is the `forgeCreator` wallet are read; those
 *    with unclaimed creator fees are claimed by the claims job to `multisigStandIn` (stand-in for
 *    FORGE_MULTISIG_VAULT), the `funder` paying the fees. These existing wallets are not in a
 *    signer keystore, so a keystore-shaped wrapper signs with them here (scripts/devnet-tests is
 *    the only place allowed to hold such keypairs, PLANEXECUTE rule 5).
 *
 * Only public data is printed (addresses, signatures, amounts).
 */
import { randomBytes, randomUUID } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import {
  Keypair,
  PublicKey,
  SystemProgram,
  Transaction,
  TransactionInstruction,
} from '@solana/web3.js';
import { createForgeSignerCore } from '../../../apps/signer/src/core-adapter.js';
import { creatorRole, openKeystore } from '../../../apps/signer/src/keystore.js';
import {
  ClaimJournalEntry,
  createClaimsJob,
  type CreatorLaunchpad,
} from '../../../apps/signer/src/jobs/claims.js';
import {
  RefundJournalEntry,
  RefundManualMark,
  createFileRefundLedger,
  createRefundsJob,
} from '../../../apps/signer/src/jobs/refunds.js';
import {
  createFileJournal,
  createMemoryJournal,
  Mutex,
  rpcFromConnection,
} from '../../../apps/signer/src/jobs/shared.js';
import { MemoryRefundDb, memoryFlags } from '../../../apps/signer/src/jobs/testing.js';
import { runMain } from './lib/funding.js';
import { STATE_DIR, loadEnv } from './lib/env.js';
import { State, type Json } from './lib/state.js';
import { loadWallets } from './lib/wallets.js';
import { consoleAlerter, consoleLogger, walletKeystore } from './lib/signer-harness.js';
import {
  formatSol,
  getBalance,
  getConnection,
  sendAndConfirm,
  sleep,
  solscanTx,
  transferSol,
} from './lib/solana.js';

const REFUND_LAMPORTS = 1_000_000n; // 0.001 SOL
const MEMO_PROGRAM_ID = new PublicKey('MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr');
const WORK_DIR = resolve(STATE_DIR, 'signer-claims');
/** Devnet: claim whatever is there (the temporary WSOL rent goes to the stand-in vault anyway). */
const DEVNET_MIN_CLAIM_LAMPORTS = 1_000n;

/** Throwaway passphrase for the devnet keystore, kept in .state (devnet stand-in only). */
function devnetPassphrase(): string {
  if (!existsSync(WORK_DIR)) mkdirSync(WORK_DIR, { recursive: true });
  const file = resolve(WORK_DIR, 'keystore-passphrase.txt');
  if (!existsSync(file)) {
    writeFileSync(file, randomBytes(32).toString('hex'), { encoding: 'utf8', mode: 0o600 });
  }
  return readFileSync(file, 'utf8').trim();
}

async function waitFinalized(signature: string): Promise<void> {
  const connection = getConnection();
  for (let i = 0; i < 60; i++) {
    const status = (
      await connection.getSignatureStatuses([signature], { searchTransactionHistory: true })
    ).value[0];
    if (status?.err) throw new Error(`payment failed on-chain: ${JSON.stringify(status.err)}`);
    if (status?.confirmationStatus === 'finalized') return;
    await sleep(2_000);
  }
  throw new Error('payment not finalized after 120 s');
}

interface RefundSeed {
  [key: string]: Json;
  jobId: string;
  launchpadId: string;
  paymentId: string;
  paymentSignature: string;
  cashbox: string;
}

async function refundPart(state: State, wallets: ReturnType<typeof loadWallets>): Promise<boolean> {
  console.log('\n=== 1. Refund of a twice-failed build (0.001 SOL) ===');
  const connection = getConnection();
  const keystore = await openKeystore({
    dir: resolve(WORK_DIR, 'keystore'),
    passphrase: devnetPassphrase(),
  });
  try {
    const cashbox = (await keystore.createKey('cashbox')).publicKey;
    console.log(`  cashbox stand-in (keystore-generated): ${cashbox.toBase58()}`);
    const client = wallets.client.publicKey;

    // Before the payment only: fund the cashbox with rent + 0.002 SOL (refund + fees).
    const rent = BigInt(await connection.getMinimumBalanceForRentExemption(0));
    const target = rent + 2_000_000n;
    const have = await getBalance(cashbox);
    if (!state.has('signerClaims.refund.payment') && have < target) {
      console.log(`  funding the cashbox with ${formatSol(target - have)}`);
      await transferSol(wallets.funder, cashbox, target - have, 'fund cashbox');
    }

    // The client's payment (memo forge:job:<jobId>), once.
    const seed = await state.step<RefundSeed>('signerClaims.refund.payment', async () => {
      const jobId = randomUUID();
      const tx = new Transaction().add(
        SystemProgram.transfer({
          fromPubkey: client,
          toPubkey: cashbox,
          lamports: REFUND_LAMPORTS,
        }),
        new TransactionInstruction({
          programId: MEMO_PROGRAM_ID,
          keys: [{ pubkey: client, isSigner: true, isWritable: false }],
          data: Buffer.from(`forge:job:${jobId}`, 'utf8'),
        }),
      );
      const paymentSignature = await sendAndConfirm(tx, wallets.client, {
        label: 'client payment',
      });
      return {
        jobId,
        launchpadId: randomUUID(),
        paymentId: randomUUID(),
        paymentSignature,
        cashbox: cashbox.toBase58(),
      };
    });
    if (seed.cashbox !== cashbox.toBase58()) throw new Error('cashbox changed since the payment');
    console.log(`  payment: ${solscanTx(seed.paymentSignature)}`);
    await waitFinalized(seed.paymentSignature);

    // The database rows (in memory, persisted in .state between runs).
    const db = new MemoryRefundDb();
    const saved = state.get<{
      jobStatus: string;
      paymentStatus: string;
      refundSignature: string | null;
    }>('signerClaims.refund.db');
    const job = db.addJob({
      id: seed.jobId,
      launchpadId: seed.launchpadId,
      type: 'create_launchpad',
      status: (saved?.jobStatus ?? 'failed') as 'failed',
      attempts: 2,
      failedStage: 'build',
      lockedAt: null,
      ownerWallet: client.toBase58(),
    });
    db.addPayment(job, {
      id: seed.paymentId,
      payerWallet: client.toBase58(),
      kind: 'creation',
      lamports: REFUND_LAMPORTS,
      txSignature: seed.paymentSignature,
      status: (saved?.paymentStatus ?? 'confirmed') as 'confirmed',
      refundSignature: saved?.refundSignature ?? null,
    });
    const persist = () => {
      const p = db.payments.get(seed.paymentId)!;
      state.set('signerClaims.refund.db', {
        jobStatus: db.jobs.get(seed.jobId)!.status,
        paymentStatus: p.status,
        refundSignature: p.refundSignature,
      });
    };

    const alerts: string[] = [];
    const announced: string[] = [];
    const makeJob = () =>
      createRefundsJob({
        store: db,
        rpc: rpcFromConnection(connection),
        core: createForgeSignerCore({ connection, cashbox, cluster: 'devnet' }),
        keystore,
        journal: createFileJournal({
          dir: resolve(WORK_DIR, 'journal'),
          namespace: 'refunds',
          schema: RefundJournalEntry,
        }),
        manualMarks: createMemoryJournal(RefundManualMark),
        ledger: createFileRefundLedger(resolve(WORK_DIR, 'journal')),
        walletLock: new Mutex(),
        flags: memoryFlags(),
        alerter: consoleAlerter(alerts),
        logger: consoleLogger('refunds'),
        config: { cashbox, maxRefundLamports: 10_000_000n },
        onBeforeSend: (s) => void announced.push(s),
      });

    const clientBefore = await getBalance(client);
    const first = await makeJob().runOnce();
    persist();
    console.log(`  run 1: ${first.status} ${JSON.stringify(first.outcomes.map((o) => o.result))}`);
    const second = await makeJob().runOnce();
    persist();
    console.log(
      `  run 2: ${second.status} ${JSON.stringify(second.outcomes.map((o) => o.result))}`,
    );

    const payment = db.payments.get(seed.paymentId)!;
    const refundSignature = payment.refundSignature;
    const clientAfter = await getBalance(client);
    console.log(`  refund: ${refundSignature ? solscanTx(refundSignature) : 'none'}`);
    console.log(`  client balance: ${formatSol(clientBefore)} -> ${formatSol(clientAfter)}`);
    let landedAmount = 0n;
    if (refundSignature) {
      const tx = await connection.getTransaction(refundSignature, {
        commitment: 'finalized',
        maxSupportedTransactionVersion: 0,
      });
      const keys = tx?.transaction.message.getAccountKeys();
      const clientIndex = keys
        ? [...Array(keys.length).keys()].find((i) => keys.get(i)?.equals(client))
        : undefined;
      if (tx?.meta && clientIndex !== undefined) {
        landedAmount =
          BigInt(tx.meta.postBalances[clientIndex]!) - BigInt(tx.meta.preBalances[clientIndex]!);
      }
    }
    const checks: Array<[string, boolean]> = [
      ['payment refunded in the store', payment.status === 'refunded'],
      ['job refunded in the store', db.jobs.get(seed.jobId)!.status === 'refunded'],
      [
        'client received exactly 0.001 SOL in the refund transaction',
        landedAmount === REFUND_LAMPORTS,
      ],
      ['second run sent nothing', second.outcomes.every((o) => o.result !== 'refunded')],
      [
        'onBeforeSend saw at most the refund signature',
        announced.every((s) => s === refundSignature),
      ],
    ];
    for (const [label, ok] of checks) console.log(`  ${ok ? 'OK  ' : 'FAIL'} ${label}`);
    state.set('signerClaims.refund.result', {
      refundSignature,
      paymentSignature: seed.paymentSignature,
      ok: checks.every(([, ok]) => ok),
    });
    return checks.every(([, ok]) => ok);
  } finally {
    await keystore.close();
  }
}

async function claimPart(state: State, wallets: ReturnType<typeof loadWallets>): Promise<boolean> {
  console.log('\n=== 2. Creator-fee claim to the multisig stand-in ===');
  const connection = getConnection();
  const core = createForgeSignerCore({
    connection,
    cashbox: wallets.funder.publicKey,
    cluster: 'devnet',
  });
  const vault = wallets.multisigStandIn.publicKey;
  const pools = ['test2.pool', 'test3.launch', 'test4.pool', 'test1.pool']
    .map((key) => state.get<{ pool: string }>(key)?.pool)
    .filter((p): p is string => typeof p === 'string');
  const launchpads: CreatorLaunchpad[] = [];
  const roles: Record<string, Keypair> = { payer: wallets.funder };
  for (const address of pools) {
    const pool = new PublicKey(address);
    const st = await core.readCreatorPool(pool);
    if (!st) {
      console.log(`  ${address}: not found`);
      continue;
    }
    const mine = st.creator.equals(wallets.forgeCreator.publicKey);
    console.log(
      `  ${address}: creator ${mine ? 'forgeCreator' : st.creator.toBase58()}, graduated ${st.graduated}, unclaimed creator share ${formatSol(st.creatorClaimable.quote)}`,
    );
    if (!mine || st.creatorClaimable.quote === 0n) continue;
    if (!core.coinPoolAddress(st.config, st.baseMint).equals(pool)) {
      throw new Error(`pool address derivation mismatch for ${address}`);
    }
    const id = randomUUID();
    roles[creatorRole(id)] = wallets.forgeCreator;
    launchpads.push({
      id,
      status: 'live',
      coinConfig: st.config.toBase58(),
      coinMint: st.baseMint.toBase58(),
      creatorWalletRef: '',
    });
  }
  if (launchpads.length === 0) {
    console.log('  nothing claimable on the wave-1 pools: claim part skipped');
    state.set('signerClaims.claim.result', { claimed: [], ok: true, skipped: true });
    return true;
  }
  const keystore = walletKeystore(roles);
  for (const lp of launchpads) lp.creatorWalletRef = (await keystore.findRef(creatorRole(lp.id)))!;

  const alerts: string[] = [];
  const vaultBefore = await getBalance(vault);
  const job = createClaimsJob({
    store: { listCreatorLaunchpads: async () => launchpads },
    core,
    rpc: rpcFromConnection(connection),
    keystore,
    journal: createFileJournal({
      dir: resolve(WORK_DIR, 'journal'),
      namespace: 'claims',
      schema: ClaimJournalEntry,
    }),
    flags: memoryFlags(),
    alerter: consoleAlerter(alerts),
    logger: consoleLogger('claims'),
    config: { vault, minClaimLamports: DEVNET_MIN_CLAIM_LAMPORTS, feePayer: 'payer' },
    onBeforeSend: () => undefined,
  });
  const report = await job.runOnce();
  const claimed = report.outcomes.filter((o) => o.result === 'claimed') as Array<{
    pool?: string;
    signature: string;
    lamports: bigint;
  }>;
  for (const o of report.outcomes) {
    console.log(
      `  ${o.pool ?? o.launchpadId}: ${o.result}${'signature' in o ? ` ${solscanTx(o.signature)}` : ''}`,
    );
  }
  const vaultAfter = await getBalance(vault);
  const expected = claimed.reduce((a, c) => a + c.lamports, 0n);
  console.log(`  multisigStandIn balance: ${formatSol(vaultBefore)} -> ${formatSol(vaultAfter)}`);
  const again = await job.runOnce();
  console.log(`  run 2: ${JSON.stringify(again.outcomes.map((o) => o.result))}`);
  const ok =
    report.status === 'ran' &&
    claimed.length > 0 &&
    vaultAfter - vaultBefore >= expected &&
    again.outcomes.every((o) => o.result !== 'claimed');
  console.log(
    `  ${ok ? 'OK  ' : 'FAIL'} creator share claimed to the stand-in vault (>= ${formatSol(expected)})`,
  );
  state.set('signerClaims.claim.result', {
    claimed: claimed.map((c) => ({
      pool: c.pool ?? null,
      signature: c.signature,
      lamports: c.lamports.toString(),
    })),
    ok,
  });
  return ok;
}

async function main(): Promise<void> {
  loadEnv(); // throws unless RPC_URL contains "devnet"
  const state = State.load();
  const wallets = loadWallets();
  const refundOk = await refundPart(state, wallets);
  const claimOk = await claimPart(state, wallets);
  console.log(
    `\nSigner jobs on devnet: refund ${refundOk ? 'PASS' : 'FAIL'}, claim ${claimOk ? 'PASS' : 'FAIL'}`,
  );
  if (!refundOk || !claimOk) process.exitCode = 1;
}

await runMain(main);
